import heapq


def last_stone(stones: list[int]) -> int:
    heap = [-s for s in stones]              # max-heap: the weights are negated
    heapq.heapify(heap)
    while len(heap) > 1:
        y = -heapq.heappop(heap)             # the heaviest
        x = -heapq.heappop(heap)             # the second heaviest
        if y > x:
            heapq.heappush(heap, x - y)      # what is left, y - x, negated
    return -heap[0] if heap else 0

perf.naive:
def last_stone(stones: list[int]) -> int:
    pile = list(stones)
    while len(pile) > 1:
        pile.sort()                          # re-sort the whole pile every turn
        y, x = pile.pop(), pile.pop()
        if y != x:
            pile.append(y - x)
    return pile[0] if pile else 0
